import { useRef, useState } from "react";
import { IconKeyboard } from "../../icons/generated/icons.js";
import { Button } from "../../ui/button/index.js";
import { SearchField } from "../../ui/input/index.js";
import { KeyboardPopover } from "../../ui/on-screen-keyboard/index.js";
import { SectionPage, Specimen } from "../kit.js";

function PopoverDemo() {
  const field = useRef<HTMLInputElement>(null);
  const toggle = useRef<HTMLButtonElement>(null);
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(false);
  return (
    <div className="gallery-osk-pad" data-width="narrow">
      <SearchField
        ref={field}
        aria-label="Search the catalogue"
        value={query}
        onValueChange={setQuery}
        enterKeyHint="search"
        onClick={() => setOpen(true)}
        trailing={
          <Button
            ref={toggle}
            variant="ghost"
            size="sm"
            icon={<IconKeyboard />}
            aria-label="Keyboard"
            aria-pressed={open}
            onPointerDown={(event) => event.preventDefault()}
            onClick={() => {
              setOpen((previous) => !previous);
              field.current?.focus();
            }}
          />
        }
      />
      <KeyboardPopover
        target={field}
        open={open}
        layout="qwerty"
        size="sm"
        onOpenChange={(next, details) => {
          // The toggle beside the field opens and closes it itself.
          if (
            !next &&
            details.event?.target instanceof Node &&
            toggle.current?.contains(details.event.target)
          )
            return;
          setOpen(next);
        }}
      />
    </div>
  );
}

export default function OnScreenKeyboardSection() {
  return (
    <SectionPage>
      <Specimen
        title="Popover on a search field"
        description="KeyboardPopover anchored to its target. Tap the field or the keyboard button; a press outside closes it."
        specimenKey="on-screen-keyboard:default:7"
      >
        <PopoverDemo />
      </Specimen>
    </SectionPage>
  );
}
